 const DOMParser = require('xmldom').DOMParser;
 const XMLSerializer = require('xmldom').XMLSerializer;

+/**
+ * Sanitize SVG DOM by removing elements and attributes that could lead to XSS.
+ * @param {Document} svgDom The parsed SVG document to sanitize in-place.
+ */
+const sanitizeSvg = function (svgDom) {
+    // Remove <script> elements
+    const scripts = svgDom.getElementsByTagName('script');
+    for (let i = scripts.length - 1; i >= 0; i--) {
+        scripts[i].parentNode.removeChild(scripts[i]);
+    }
+
+    // Remove dangerous attributes from all elements
+    const allElements = svgDom.getElementsByTagName('*');
+    for (let i = 0; i < allElements.length; i++) {
+        const el = allElements[i];
+        const attrs = el.attributes;
+        for (let j = attrs.length - 1; j >= 0; j--) {
+            const attrName = attrs[j].name.toLowerCase();
+            const attrValue = (attrs[j].value || '').trim().toLowerCase();
+            // Remove event handler attributes (e.g., onclick, onload)
+            if (attrName.startsWith('on')) {
+                el.removeAttribute(attrs[j].name);
+            }
+            // Remove javascript: URLs in href attributes
+            if ((attrName === 'href' || attrName === 'xlink:href') &&
+                attrValue.startsWith('javascript:')) {
+                el.removeAttribute(attrs[j].name);
+            }
+        }
+    }
+
+    // Remove <foreignObject> elements (can embed HTML with scripts)
+    const foreignObjects = svgDom.getElementsByTagName('foreignObject');
+    for (let i = foreignObjects.length - 1; i >= 0; i--) {
+        foreignObjects[i].parentNode.removeChild(foreignObjects[i]);
+    }
+};
