+/// Verify the QE Identity JSON signature using the provided issuer chain.
+fn verify_qe_identity_signature(
+    qe_identity_json: &[u8],
+    signature: &[u8],
+    issuer_chain_pem: &[u8],
+) -> Result<(), Error> {
+    let chain = parse_certificate_chain(issuer_chain_pem)
+        .map_err(|e| Error::CertificateError(format!("Failed to parse issuer chain: {}", e)))?;
+
+    if chain.is_empty() {
+        return Err(Error::CertificateError("Empty issuer chain".into()));
+    }
+
+    // Validate the certificate chain up to the Intel SGX Root CA
+    validate_chain_of_trust(&chain)?;
+
+    // Verify the ECDSA-P256-SHA256 signature over the QE Identity JSON
+    let signing_cert = &chain[0];
+    verify_ecdsa_signature(signing_cert, qe_identity_json, signature)
+        .map_err(|e| Error::SignatureError(
+            format!("QE Identity signature verification failed: {}", e)
+        ))?;
+
+    Ok(())
+}
+
+/// Enforce policy constraints on the QE Report against the QE Identity.
+fn enforce_qe_report_policy(
+    qe_identity: &QeIdentity,
+    qe_report_body: &ReportBody,
+) -> Result<(), Error> {
+    // Verify MRSIGNER
+    let expected_mrsigner = hex::decode(&qe_identity.mrsigner)
+        .map_err(|e| Error::DeserializationError(format!("Invalid MRSIGNER: {}", e)))?;
+    if qe_report_body.mrsigner.as_ref() != expected_mrsigner.as_slice() {
+        return Err(Error::PolicyViolation(
+            "QE Report MRSIGNER does not match QE Identity".into()
+        ));
+    }
+
+    // Verify ISVPRODID
+    if qe_report_body.isv_prod_id != qe_identity.isvprodid {
+        return Err(Error::PolicyViolation(
+            "QE Report ISVPRODID does not match QE Identity".into()
+        ));
+    }
+
+    // Verify ATTRIBUTES against mask
+    let expected_attrs = hex::decode(&qe_identity.attributes)
+        .map_err(|e| Error::DeserializationError(format!("Invalid attributes: {}", e)))?;
+    let attrs_mask = hex::decode(&qe_identity.attributes_mask)
+        .map_err(|e| Error::DeserializationError(format!("Invalid attributes_mask: {}", e)))?;
+    for i in 0..expected_attrs.len() {
+        if (qe_report_body.attributes[i] & attrs_mask[i]) != (expected_attrs[i] & attrs_mask[i]) {
+            return Err(Error::PolicyViolation(
+                "QE Report ATTRIBUTES do not match QE Identity policy".into()
+            ));
+        }
+    }
+
+    // Verify MISCSELECT against mask
+    let expected_misc = hex::decode(&qe_identity.miscselect)
+        .map_err(|e| Error::DeserializationError(format!("Invalid miscselect: {}", e)))?;
+    let misc_mask = hex::decode(&qe_identity.miscselect_mask)
+        .map_err(|e| Error::DeserializationError(format!("Invalid miscselect_mask: {}", e)))?;
+    for i in 0..expected_misc.len() {
+        if (qe_report_body.misc_select[i] & misc_mask[i]) != (expected_misc[i] & misc_mask[i]) {
+            return Err(Error::PolicyViolation(
+                "QE Report MISCSELECT does not match QE Identity policy".into()
+            ));
+        }
+    }
+
+    Ok(())
+}
