+package org.apache.streampipes.manager.util;
+
+import java.net.InetAddress;
+import java.net.URI;
+import java.net.UnknownHostException;
+
+public class SsrfValidator {
+
+  private SsrfValidator() {
+    throw new AssertionError("Utility class");
+  }
+
+  /**
+   * Validates that the given URL is safe to request from the server side,
+   * i.e. it does not point to an internal or private network address.
+   *
+   * @param url the URL to validate
+   * @throws IllegalArgumentException if the URL is not safe
+   */
+  public static void validateUrl(String url) {
+    if (url == null || url.isBlank()) {
+      throw new IllegalArgumentException("URL must not be null or blank");
+    }
+
+    URI uri;
+    try {
+      uri = new URI(url);
+    } catch (Exception e) {
+      throw new IllegalArgumentException("Invalid URL: " + url, e);
+    }
+
+    String scheme = uri.getScheme();
+    if (scheme == null || (!scheme.equalsIgnoreCase("http") && !scheme.equalsIgnoreCase("https"))) {
+      throw new IllegalArgumentException("Only http and https schemes are allowed");
+    }
+
+    String host = uri.getHost();
+    if (host == null || host.isBlank()) {
+      throw new IllegalArgumentException("URL must contain a valid host");
+    }
+
+    try {
+      InetAddress address = InetAddress.getByName(host);
+      if (address.isLoopbackAddress()
+          || address.isLinkLocalAddress()
+          || address.isSiteLocalAddress()
+          || address.isAnyLocalAddress()
+          || address.isMulticastAddress()) {
+        throw new IllegalArgumentException(
+            "URL must not point to an internal or private network address");
+      }
+    } catch (UnknownHostException e) {
+      throw new IllegalArgumentException("Could not resolve host: " + host, e);
+    }
+  }
+}

